// Runs the committed resume-parser benchmark corpus (the same corpus that
// gates the Electron Anydoc parser) through the web runtime's document parser.
// Fixtures are generated by scripts/generate-resume-parser-fixtures.py.
import { readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { unzipSync } from "fflate";
import * as pdfjs from "pdfjs-dist/legacy/build/pdf.mjs";
import * as pdfjsWorker from "pdfjs-dist/legacy/build/pdf.worker.mjs";
import {
  classifyCompoundFile,
  detectDocumentFormat,
  DocumentTextError,
  extractDocxText,
  extractPdfText,
} from "../src/pwa/runtime/document-text.ts";

globalThis.pdfjsWorker = pdfjsWorker;
const root = path.join(path.dirname(fileURLToPath(import.meta.url)), "fixtures", "career-evidence", "parser-benchmark");
const manifest = JSON.parse(await readFile(path.join(root, "manifest.json"), "utf8"));
const normalize = (value) => value.normalize("NFKC").toLowerCase().replace(/[‐-―]/g, "-").replace(/\s+/g, " ").trim();

async function parse(bytes) {
  const format = detectDocumentFormat(bytes);
  if (format === "cfb") throw classifyCompoundFile(bytes);
  if (format === "docx") return extractDocxText(bytes, unzipSync);
  if (format === "pdf") {
    const pdf = await extractPdfText(bytes, pdfjs);
    if (pdf.emptyPages.length === pdf.pageCount) throw new DocumentTextError("needs OCR", "ocr-required", pdf.emptyPages);
    return pdf.text;
  }
  const text = new TextDecoder().decode(bytes);
  if (/[\u0000-\u0008]/.test(text)) throw new DocumentTextError("unsupported", "unsupported");
  return text;
}

let failures = 0;
for (const fixture of manifest.fixtures) {
  const bytes = new Uint8Array(await readFile(path.join(root, fixture.file)));
  let outcome = "success";
  let text = "";
  try {
    text = await parse(bytes);
  } catch (error) {
    outcome = error instanceof DocumentTextError ? error.code : "parser-failure";
  }
  const expected = fixture.expectedOutcome === "success" ? "success" : fixture.expectedFailureClass;
  let ok = outcome === expected;
  let detail = "";
  if (ok && outcome === "success") {
    const haystack = normalize(text);
    const missing = (fixture.expectedPhrases ?? []).filter((phrase) => !haystack.includes(normalize(phrase)));
    const forbidden = (fixture.forbiddenPhrases ?? []).filter((phrase) => haystack.includes(normalize(phrase)));
    let cursor = -1;
    const disordered = [];
    for (const phrase of fixture.mustAppearInOrder ?? []) {
      const index = haystack.indexOf(normalize(phrase));
      if (index < cursor) disordered.push(phrase);
      cursor = Math.max(cursor, index);
    }
    ok = missing.length === 0 && forbidden.length === 0 && disordered.length === 0;
    detail = JSON.stringify({ missing, forbidden, disordered });
  }
  console.log(`${ok ? "ok  " : "FAIL"} ${fixture.id}: expected ${expected}, got ${outcome} ${ok ? "" : detail}`);
  if (!ok) failures += 1;
}
if (failures > 0) {
  console.error(`${failures} web parser benchmark fixture(s) failed`);
  process.exit(1);
}
console.log(`Web document parser matched all ${manifest.fixtures.length} benchmark fixtures.`);
